    function run(address owner, address spender, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public {
        require(deadline < block.timestamp);
        uint256 beforeAllowance = c.allowance(owner, spender); if (__ESBMC_reverted()) return;

        bool reverted;
        c.permit(owner, spender, 1, deadline, v, r, s); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
